tasks.setup:
// The assembler's opcode table — one entry per mnemonic.
const OPCODES = { LOAD: 0, STORE: 1, ADD: 2, SUB: 3, JUMP: 4, HALT: 5 };

// One line of assembly: just the mnemonic part for this drill.
const program = ['LOAD', 'ADD', 'STORE'];

tasks.code:
// Translate each mnemonic to its opcode number (1:1 lookup).
for (const mnemonic of program) {
  const opcode = OPCODES[mnemonic];
  console.log(mnemonic + ' -> opcode ' + opcode);
}
